+        post("/reservations/" + id + "/confirmation", "");
+        post("/reservations/" + id + "/check-in", "");
+        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
+        JsonNode document = json.readTree(checkedOut.body());
+        assertEquals("Booking receipt", document.get("title").asText());
+        assertTrue(document.get("text").asText().contains("passport X1234567"));
+        assertTrue(document.get("text").asText().contains("Check-in: 2027-03-10"));
+        assertTrue(document.get("text").asText().contains("BRL"));
+    }
+
+    @Test
+    void requiresExactlyOneIdentityType() throws Exception {
+        String noIdentity = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response1 = post("/reservations", noIdentity);
+        assertEquals(400, response1.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response1.body()).get("error").asText());
+
+        String twoIdentities = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Test",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response2 = post("/reservations", twoIdentities);
+        assertEquals(400, response2.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response2.body()).get("error").asText());
+    }
