  1	package hotel.reservations;
  2	
  3	import hotel.documents.DocumentGenerators;
  4	import hotel.documents.ReservationReceipt;
  5	import hotel.messages.EmailSender;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.Rooms;
  8	import java.math.BigDecimal;
  9	
 10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 11	public final class ReservationService {
 12	
 13	    static final String HOTEL_NAME = "Pousada Maré Alta";
 14	
 15	    private final Rooms rooms;
 16	    private final ReservationStore store;
 17	    private final PriceCalculator priceCalculator;
 18	    private final EmailSender emailSender;
 19	
 20	    public ReservationService(
 21	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 22	        this.rooms = rooms;
 23	        this.store = store;
 24	        this.priceCalculator = priceCalculator;
 25	        this.emailSender = emailSender;
 26	    }
 27	
 28	    public synchronized Reservation create(NewReservation request) {
 29	        if (!request.checkOut().isAfter(request.checkIn())) {
 30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 31	        }
 32	        if (request.guests() < 1) {
 33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 34	        }
 35	        Room room = rooms.find(request.roomNumber())
 36	                .orElseThrow(() -> new HotelException(
 37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 38	        if (request.guests() > room.capacity()) {
 39	            throw new HotelException(
 40	                    ErrorCode.CAPACITY_EXCEEDED,
 41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 42	        }
 43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 44	            throw new HotelException(
 45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 46	        }
 47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 48	        return store.add(request, price);
 49	    }
 50	
 51	    public Reservation find(long reservationId) {
 52	        return store.find(reservationId)
 53	                .orElseThrow(() -> new HotelException(
 54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 55	    }
 56	
 57	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 58	    public synchronized Reservation confirm(long reservationId) {
 59	        Reservation reservation = find(reservationId);
 60	        if (reservation.status() != ReservationStatus.PENDING) {
 61	            throw notAllowed(reservation, "confirm");
 62	        }
 63	        reservation.confirmPayment();
 64	        store.update(reservation);
 65	        ReservationReceipt receipt = DocumentGenerators.forIdentity(reservation.guest().identity())
 66	                .generate(reservation, roomOf(reservation));
 67	        emailSender.send(
 68	                reservation.guest().email(),
 69	                "Reserva confirmada - " + HOTEL_NAME,
 70	                confirmationEmailBody(reservation, receipt));
 71	        return reservation;
 72	    }
 73	
 74	    /**
 75	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 76	     * reservation was never paid, so nothing comes back).
 77	     */
 78	    public synchronized Reservation cancel(long reservationId) {
 79	        Reservation reservation = find(reservationId);
 80	        if (reservation.status() != ReservationStatus.PENDING
 81	                && reservation.status() != ReservationStatus.CONFIRMED) {
 82	            throw notAllowed(reservation, "cancel");
 83	        }
 84	        BigDecimal refund = switch (reservation.ratePlan()) {
 85	            case STANDARD -> reservation.amountPaid();
 86	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 87	        };
 88	        reservation.cancel(refund);
 89	        store.update(reservation);
 90	        return reservation;
 91	    }
 92	
 93	    public synchronized Reservation checkIn(long reservationId) {
 94	        Reservation reservation = find(reservationId);
 95	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 96	            throw notAllowed(reservation, "check in");
 97	        }
 98	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 99	        store.update(reservation);
100	        return reservation;
101	    }
102	
103	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
104	    public synchronized ReservationReceipt checkOut(long reservationId) {
105	        Reservation reservation = find(reservationId);
106	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
107	            throw notAllowed(reservation, "check out");
108	        }
109	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
110	        store.update(reservation);
111	        return DocumentGenerators.forIdentity(reservation.guest().identity())
112	                .generate(reservation, roomOf(reservation));
113	    }
114	
115	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
116	    public ReservationReceipt receiptCopy(long reservationId) {
117	        Reservation reservation = find(reservationId);
118	        if (!reservation.isPaid()) {
119	            throw notAllowed(reservation, "issue a receipt for");
120	        }
121	        return DocumentGenerators.forIdentity(reservation.guest().identity())
122	                .generate(reservation, roomOf(reservation));
123	    }
124	
125	    private Room roomOf(Reservation reservation) {
126	        return rooms.find(reservation.roomNumber()).orElseThrow();
127	    }
128	
129	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
130	        return "Olá, " + reservation.guest().name() + "!\n\n"
131	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
132	                + receipt.text() + "\n"
133	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
134	                + "Até breve!\n";
135	    }
136	
137	    private static HotelException notAllowed(Reservation reservation, String operation) {
138	        return new HotelException(
139	                ErrorCode.OPERATION_NOT_ALLOWED,
140	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
141	    }
142	}
